1766	              unprocessedSections));
1767	        }
1768	        throw new IOException("Got unexpected tag end event for " +
1769	            ev.asEndElement().getName().getLocalPart() + " while looking " +
1770	            "for section header tag.");
1771	      } else if (ev.getEventType() != XMLStreamConstants.START_ELEMENT) {
1772	        throw new IOException("Expected section header START_ELEMENT; " +
1773	            "got event of type " + ev.getEventType());
1774	      }
1775	      String sectionName = ev.asStartElement().getName().getLocalPart();
